package com.nextrade.domain.portfolio; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; import com.nextrade.domain.shared.*; import java.util.*;
public final class Portfolio extends AbstractAggregateRoot<PortfolioId>{private final UserId userId;private final Map<InstrumentId,Holding> holdings=new LinkedHashMap<>();public Portfolio(PortfolioId id,UserId userId){super(id);this.userId=userId;}public static Portfolio create(UserId user){return new Portfolio(PortfolioId.generate(),user);}public Holding holding(InstrumentId id){return holdings.computeIfAbsent(id,Holding::new);}public Collection<Holding> holdings(){return List.copyOf(holdings.values());}public UserId userId(){return userId;}}
